---RefreshUI
---@param data table cellState quizData playerId info rank
function PVPArenaQuizListCell:RefreshUI(data, goodsId)
    local info     = data.info
    local playerId = data.playerId
    local excludeDialogs = {}
    PVPArenaUtils.RefreshPlayerHeadNode(self.PlayerHeadNode.gameObject, playerId, info, excludeDialogs)

    self.TextName.text = info.name
    self.TxtLV.text = info.level

    local cellState = data.cellState
    local isRewardPreview = cellState == CellState.RewardPreview
    KTool.SetActive(self.State1.gameObject, isRewardPreview)
    KTool.SetActive(self.State2.gameObject, cellState == CellState.InBattle)
    KTool.SetActive(self.State3.gameObject, cellState == CellState.Prepare)

    if isRewardPreview then
        PVPArenaUtils.RefreshPVPRankFlagNode(self.PVPRankFlagNode.gameObject, data.rank)
        self.Image:LoadSprite(goodsConfMgr:GetPhotoPathById(goodsId))
        self.TxtNumber.text = data.rewardNum
    end
end

